import itertools, math

def joint_pair_count(N: int, i: int, j: int) -> int:
    """Number of codes in which neurons i and j are both active."""
    return sum(1 for c in itertools.product((0, 1), repeat=N)
               if c[i] == 1 and c[j] == 1)

def single_active_count(N: int, i: int) -> int:
    """Number of codes in which neuron i is active."""
    return sum(1 for c in itertools.product((0, 1), repeat=N) if c[i] == 1)

# First-order symmetry: single neuron active in 2^(N-1) codes.
# Second-order symmetry: distinct pair jointly active in 2^(N-2) codes.
for N in range(2, 10):
    s = single_active_count(N, 0)
    p = joint_pair_count(N, 0, 1)
    print(f"N={N}: single {s}=2^(N-1)={2**(N-1)},  "
          f"pair {p}=2^(N-2)={2**(N-2)}")

import math

def deviating_fraction_exact(N: int, t: float) -> float:
    """Exact fraction of codes with |weight - N/2| >= t, via C(N,k)."""
    mean = N / 2.0
    hits = sum(math.comb(N, k) for k in range(N + 1) if abs(k - mean) >= t)
    return hits / (2 ** N)

def chebyshev_ceiling(N: int, t: float) -> float:
    """Chebyshev upper bound N/(4 t^2)."""
    return N / (4.0 * t * t)

def subgaussian_ceiling(N: int, t: float) -> float:
    """Conjectured sub-Gaussian bound 2 exp(-2 t^2 / N)."""
    return 2.0 * math.exp(-2.0 * t * t / N)

# At the one-sigma-scale window t = sqrt(N), the theorem guarantees that
# at least 3/4 of all codes lie within sqrt(N) of the mean N/2.
for N in (16, 64, 256, 1024):
    t = math.sqrt(N)
    exact = deviating_fraction_exact(N, t)
    print(f"N={N:>5}: within sqrt(N) = {1-exact:.4f} (>=0.75), "
          f"exact tail {exact:.4f}, Chebyshev {chebyshev_ceiling(N,t):.4f}, "
          f"sub-Gaussian {subgaussian_ceiling(N,t):.4f}")

