function BINOMIAL_MOMENT(N, m):
    total <- 0
    for k from 0 to N:
        total <- total + C(N, k) * k^m
    return total

function MOMENTS(N):
    m1 <- BINOMIAL_MOMENT(N, 1)          # = N * 2^(N-1)
    m2 <- BINOMIAL_MOMENT(N, 2)          # = 2^N N(N+1)/4
    centered <- m2 - N*m1 + (N^2/4)*2^N  # = N * 2^N / 4
    variance <- centered / 2^N           # = N / 4
    return (m1, m2, centered, variance)

