import math

def binomial_moment(N: int, m: int) -> int:
    """Compute sum over all codes of weight^m in O(N) time.

    Uses the binomial profile: the number of codes of weight k is C(N, k),
    so sum_c weight(c)^m = sum_{k=0}^{N} C(N, k) * k^m, avoiding enumeration
    of the 2^N codes entirely.
    """
    return sum(math.comb(N, k) * (k ** m) for k in range(N + 1))

def moments(N: int) -> dict[str, float]:
    """Return the first moment, second moment, centered second moment and
    variance of the weight of a uniformly random neural code on N neurons."""
    m1 = binomial_moment(N, 1)
    m2 = binomial_moment(N, 2)
    centered = m2 - N * m1 + (N ** 2 / 4.0) * 2 ** N
    return {"sum_weight": m1, "sum_weight_sq": m2,
            "sum_centered_sq": centered, "variance": centered / 2 ** N}

