function DEVIATING_FRACTION(N, t):
    mean <- N / 2
    hits <- 0
    for k from 0 to N:
        if |k - mean| >= t:
            hits <- hits + C(N, k)
    return hits / 2^N

function BOUNDS(N, thresholds):
    for t in thresholds:
        exact <- DEVIATING_FRACTION(N, t)
        cheb  <- N / (4 * t^2)
        subg  <- 2 * exp(-2 * t^2 / N)
        emit (t, exact, cheb, subg)

function BRUTE_FORCE_HISTOGRAM(N):
    hist <- array of zeros indexed 0..N
    for each code c in {0,1}^N:
        w <- number of 1s in c
        hist[w] <- hist[w] + 1
    return hist          # equals C(N, k) at index k

