import itertools
from typing import Iterator

def all_codes(N: int) -> Iterator[tuple[int, ...]]:
    """Enumerate all 2^N binary neural codes on N neurons."""
    return itertools.product((0, 1), repeat=N)

def weight(code: tuple[int, ...]) -> int:
    return sum(code)

def brute_force_weight_histogram(N: int) -> dict[int, int]:
    """Tabulate, by full enumeration, how many of the 2^N codes have each
    possible weight 0..N. Ground truth for the closed-form binomial profile;
    feasible for N up to about 20."""
    hist: dict[int, int] = {k: 0 for k in range(N + 1)}
    for c in all_codes(N):
        hist[weight(c)] += 1
    return hist
